def minCost(grid, k):
    m, n = len(grid), len(grid[0])
    INF = float('inf')
    # 0 = right, 1 = left, 2 = down, 3 = up
    dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    # Directions perpendicular to each direction (a turn goes to one of these)
    perp = {0: (2, 3), 1: (2, 3), 2: (0, 1), 3: (0, 1)}

    best = INF
    prev = None   # layer for t - 1 turns
    for t in range(k + 1):
        # cur[d][r][c] = min cost to stand at (r, c), last move in direction d, exactly t turns
        cur = [[[INF] * n for _ in range(m)] for _ in range(4)]
        for d in range(4):
            dr, dc = dirs[d]
            # Process cells so that the cell we came from is already computed
            rows = range(m) if dr >= 0 else range(m - 1, -1, -1)
            cols = range(n) if dc >= 0 else range(n - 1, -1, -1)
            for r in rows:
                for c in cols:
                    pr, pc = r - dr, c - dc
                    cost = INF
                    # Start cell: pretend we arrived with any direction and 0 turns
                    if t == 0 and r == 0 and c == 0:
                        cost = 0
                    if 0 <= pr < m and 0 <= pc < n:
                        # Keep going straight in the same direction (no new turn)
                        if cur[d][pr][pc] < cost:
                            cost = cur[d][pr][pc]
                        # Or turn here, coming from a perpendicular direction in the previous layer
                        if prev is not None:
                            for pd in perp[d]:
                                if prev[pd][pr][pc] < cost:
                                    cost = prev[pd][pr][pc]
                    if cost < INF:
                        cur[d][r][c] = cost + grid[r][c]
        # Record the best way to finish with exactly t turns
        for d in range(4):
            if cur[d][m - 1][n - 1] < best:
                best = cur[d][m - 1][n - 1]
        prev = cur

    return -1 if best == INF else best
